fw:
cat > /root/nft.rules <<'NFTEOF'
flush ruleset

table inet filter {
    chain input {
        type filter hook input priority 0 ; policy drop ;
        ct state established,related accept
        iifname lo accept
        iifname eth0 accept
        iifname eth1 accept
        iifname eth2 icmp type echo-request accept
    }
    chain forward {
        type filter hook forward priority 0 ; policy drop ;
        ct state established,related accept
        iifname eth1 accept
        iifname eth2 ip protocol icmp drop
        iifname eth2 meta l4proto tcp tcp dport 80 accept
    }
    chain output {
        type filter hook output priority 0 ; policy accept ;
    }
}

table ip nat {
    chain prerouting {
        type nat hook prerouting priority dstnat ; policy accept ;
        iifname eth2 meta l4proto tcp tcp dport 8080 dnat to 10.10.110.10:80
    }
    chain postrouting {
        type nat hook postrouting priority srcnat ; policy accept ;
        ip saddr 10.10.110.0/24 oifname eth2 masquerade
    }
}
NFTEOF
